from rest_framework import viewsets, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import WebhookSubscription
from .serializers import WebhookSubscriptionSerializer

class WebhookSubscriptionViewSet(viewsets.ModelViewSet):
    serializer_class = WebhookSubscriptionSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return WebhookSubscription.objects.filter(organization=self.request.user.organization)

    @action(detail=True, methods=['put'])
    def update_destination(self, request, pk=None):
        hook = self.get_object()
        new_url = request.data.get('target_url')
        if not new_url:
            return Response({'error': 'target_url required'}, status=status.HTTP_400_BAD_REQUEST)
        hook.target_url = new_url
        hook.save(update_fields=['target_url'])
        return Response({'id': hook.id, 'target_url': hook.target_url})
